FILE: app/src/release.ts
```ts
import type { AnimationManager } from "@babylonjs/lite";
import { getAnimationGroups } from "@babylonjs/lite";

export function releaseProperty(manager: AnimationManager, target: object, path: string): void {
    const parts = path.split(".");
    const lastPart = parts[parts.length - 1];

    // Resolve the owner: the object that owns the last path component.
    // Per note 47, targetedAnimations entries store { target: owner, path: lastPart }.
    let owner: object = target;
    for (let i = 0; i < parts.length - 1; i++) {
        owner = (owner as any)[parts[i]];
    }

    for (const group of getAnimationGroups(manager)) {
        const mixer = group._propertyMixer;
        if (!mixer) continue;

        const tracks = mixer[0] as any[];
        for (let i = tracks.length - 1; i >= 0; i--) {
            if (tracks[i].mixTarget() === owner && tracks[i].mixProperty === lastPart) {
                tracks.splice(i, 1);
            }
        }
    }
}
```

I removed the matching track from each group's `_propertyMixer` track array so the group keeps playing its other tracks but no longer writes to the released property. I'm not fully certain that `_propertyMixer` is always populated at the moment `releaseProperty` is called (e.g., if it were somehow lazily built on first update rather than at `createPropertyAnimationGroup` time), but note 4 and the `_propertyMixerHandled` flag suggest it is set up at creation, so I believe this is safe.
